\begin{center}\begin{tikzpicture}[>=stealth]

\draw (0,0)--(3.2,0);\draw[->] (0,0)--(3.2,1.85) node[right]{$x$};\draw (.65,0)arc(0:30:.65)node[midway,right]{$\alpha$};
